; status.asm -- chapter 27: the status, read once a frame
; generated by gen27.py
        INCLUDE "msx.inc"
        OUTPUT "status.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Six tables of sprites in turn, 8 frames each. The interrupt routine, in
; mode 2, reads the status at the end of every paper, once, and keeps it in
; a list at log; the program sends each table after a paper has ended.
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
log     EQU $C600               ; a status a frame
next    EQU VARS                ; where the next one goes
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 160
        otir
        ld hl, log
        ld (next), hl
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP irq
        ld (IM2_JUMP), a
        ld hl, irq
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E2          ; the display on, sprites of 16 x 16, the interrupt on
        in a, (VDP_CTRL)        ; nothing left from before
        ei
        ld b, 8                 ; four on a line
w0:     halt                    ; the paper ended: the routine read the status
        djnz w0
s0:     VRAM_WRITE $1B00
        ld hl, state0
        ld c, VDP_DATA
        ld b, 17
        otir
e0:     ld b, 8                 ; six on a line
w1:     halt                    ; the paper ended: the routine read the status
        djnz w1
s1:     VRAM_WRITE $1B00
        ld hl, state1
        ld c, VDP_DATA
        ld b, 25
        otir
e1:     ld b, 8                 ; five on two lines
w2:     halt                    ; the paper ended: the routine read the status
        djnz w2
s2:     VRAM_WRITE $1B00
        ld hl, state2
        ld c, VDP_DATA
        ld b, 41
        otir
e2:     ld b, 8                 ; a fifth in colour 0
w3:     halt                    ; the paper ended: the routine read the status
        djnz w3
s3:     VRAM_WRITE $1B00
        ld hl, state3
        ld c, VDP_DATA
        ld b, 21
        otir
e3:     ld b, 8                 ; five below the paper
w4:     halt                    ; the paper ended: the routine read the status
        djnz w4
s4:     VRAM_WRITE $1B00
        ld hl, state4
        ld c, VDP_DATA
        ld b, 21
        otir
e4:     ld b, 8                 ; thirty-two, none fifth
w5:     halt                    ; the paper ended: the routine read the status
        djnz w5
s5:     VRAM_WRITE $1B00
        ld hl, state5
        ld c, VDP_DATA
        ld b, 128
        otir
e5:     ld b, 8
last:   halt
        djnz last
        di
done:   jr done

; irq: the status, read once at the end of the paper, into the list
irq:    push af
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C and the number
        push hl
        ld hl, (next)
        ld (hl), a
        inc hl
        ld (next), hl
        pop hl
        pop af
        ei
        ret

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
state0:                         ; four on a line
        db $63, $08, $08, $01
        db $63, $30, $08, $01
        db $63, $58, $08, $01
        db $63, $80, $08, $01
        db $D0
state1:                         ; six on a line
        db $63, $08, $08, $01
        db $63, $30, $08, $01
        db $63, $58, $08, $01
        db $63, $80, $08, $01
        db $63, $A8, $08, $01
        db $63, $D0, $08, $01
        db $D0
state2:                         ; five on two lines
        db $95, $08, $08, $01
        db $95, $30, $08, $01
        db $95, $58, $08, $01
        db $95, $80, $08, $01
        db $95, $A8, $08, $01
        db $31, $08, $08, $01
        db $31, $30, $08, $01
        db $31, $58, $08, $01
        db $31, $80, $08, $01
        db $31, $A8, $08, $01
        db $D0
state3:                         ; a fifth in colour 0
        db $63, $08, $08, $01
        db $63, $30, $08, $01
        db $63, $58, $08, $01
        db $63, $80, $08, $01
        db $63, $A8, $08, $00
        db $D0
state4:                         ; five below the paper
        db $C2, $08, $08, $01
        db $C2, $30, $08, $01
        db $C2, $58, $08, $01
        db $C2, $80, $08, $01
        db $C2, $A8, $08, $01
        db $D0
state5:                         ; thirty-two, none fifth
        db $06, $00, $08, $01
        db $06, $40, $08, $01
        db $06, $80, $08, $01
        db $06, $C0, $08, $01
        db $1D, $10, $08, $01
        db $1D, $50, $08, $01
        db $1D, $90, $08, $01
        db $1D, $D0, $08, $01
        db $34, $20, $08, $01
        db $34, $60, $08, $01
        db $34, $A0, $08, $01
        db $34, $E0, $08, $01
        db $4B, $30, $08, $01
        db $4B, $70, $08, $01
        db $4B, $B0, $08, $01
        db $4B, $F0, $08, $01
        db $62, $40, $08, $01
        db $62, $80, $08, $01
        db $62, $C0, $08, $01
        db $62, $00, $08, $01
        db $79, $50, $08, $01
        db $79, $90, $08, $01
        db $79, $D0, $08, $01
        db $79, $10, $08, $01
        db $90, $60, $08, $01
        db $90, $A0, $08, $01
        db $90, $E0, $08, $01
        db $90, $20, $08, $01
        db $A7, $70, $08, $01
        db $A7, $B0, $08, $01
        db $A7, $F0, $08, $01
        db $A7, $30, $08, $01
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
